#include <bits/stdc++.h>
using namespace std;using L=long long;
int main(){int n;cin>>n;vector<int>r(n);for(auto&x:r)cin>>x;int N=1<<n,full=N-1;vector<L>e(N*n),s(N*n);for(int m=1;m<N;m++)for(int v=0;v<n;v++)if(m>>v&1){int a=m^(1<<v);if(!a)e[m*n+v]=s[m*n+v]=1;else for(int u=0;u<n;u++)if(a>>u&1){if(r[u]>>v&1)e[m*n+v]+=e[a*n+u];else s[m*n+v]+=s[a*n+u];}}L H=0;for(int v=0;v<n;v++)H+=e[full*n+v];cout<<"H "<<H<<"\n";vector<L> h(N);h[0]=1;for(int m=1;m<N;m++)for(int v=0;v<n;v++)h[m]+=e[m*n+v];L rootE=0;for(int m=1;m<N;m++)if(m>>12&1)rootE+=e[m*n+12]*h[full^m];cerr<<"{\"H\":"<<H<<",\"root39_E2\":"<<rootE<<",\"root39_defect\":"<<rootE-H<<"}\n";for(int u=0;u<n;u++)for(int v=0;v<n;v++)if(r[u]>>v&1){L a=0,b=0;for(int m=1;m<N;m++)if((m>>u&1)&&!(m>>v&1)){a+=e[m*n+u]*s[(full^m)*n+v];b+=s[m*n+u]*e[(full^m)*n+v];}cout<<u<<" "<<v<<" "<<b-a<<" "<<a<<" "<<b<<"\n";}}
